/**
 * Types of the "v2" data payload (generated by
 * local_scripts/clean/export_v2.py).
 *
 * This is a completely separate data set from the hand maintained
 * `public/data.json`; nothing here is shared with `views/DataSearcher`.
 */

export interface LocalizedName {
    name?: string | null;
    name_jp?: string | null;
    name_en?: string | null;
}

export interface Ref {
    id: number;
    name?: string | null;
    name_jp?: string | null;
    name_en?: string | null;
}

export interface JobRef extends Ref {
    primary?: boolean;
}

export interface FateSkill extends LocalizedName {
    identification: number;
    type: string | null;
}

export interface CharacterListItem extends LocalizedName {
    id: number;
    group: number;
    guide_no: number | null;
    style: string;
    is_default_style: boolean;
    rarity: Ref;
    race: Ref;
    attribute: Ref;
    gender: Ref;
    personality: Ref;
    alignment: { id: number; name: string; point: number };
    jobs: JobRef[];
    fate: FateSkill | null;
    /** 克己：``extra_tags`` 为比同稀有度标准值更高（或专属）的属性 */
    self_restraint: { id: number | null; extra_tags: string[] } | null;
    /** 潜在继承技能的解锁等级（``sub_inheritance_grade_id``） */
    potential_grade: number | null;
    /** 卡池组：-1 限定 / -2 联动 / 0 共用 / 1 Ⅰ组 / 2 Ⅱ组 */
    pool_group: number;
    /** 声优（手工补充） */
    character_voice: string | null;
    /** 上线日期（手工补充） */
    release_date: { date: string | null; time: string | null; milliseconds: number } | null;
    images?: {
        image?: string | null;
        /** thumbnail sprite stem, e.g. ``tmb_chara_01001_00_02`` */
        thumbnail?: string | null;
        /** callable file name, e.g. ``tmb_chara_01001_00_02.png`` */
        thumbnail_file?: string | null;
        /** source folder of the sprite: ``chara`` / ``gasha`` */
        thumbnail_dir?: string | null;
    };
}

export interface SkillRef extends LocalizedName {
    identification: number;
    id?: number;
    level?: number;
    need_point?: number;
    skill_level?: number;
}

export interface CharacterDetail extends CharacterListItem {
    stats: {
        base: Record<StatKey, number>;
        growth: Record<StatKey, number>;
        pools: Record<string, { base: number | null; growth: number | null }>;
        growth_rate: Array<Record<string, number | null>>;
    };
    talent: {
        id: number;
        name: string | null;
        name_jp: string | null;
        min: Record<StatKey, number>;
        max: Record<StatKey, number>;
    };
    skills: {
        unique: SkillRef[];
        inherit: SkillRef[];
        potential_inherit: SkillRef[];
        discipline: SkillRef[];
        same_identifications: number[];
        exclude_inheritance: number[];
        get_lv: number | null;
    };
    mental: { id: number; value: number | null };
    grade: Ref;
    voice?: {
        speech?: Record<string, string> | string | null;
        breakup_speech?: Record<string, string> | string | null;
        voice_group_id?: number | null;
    };
}

export interface CharacterStyle {
    id: number;
    caption: string;
    is_default: boolean;
    awakening: number | null;
    before_awakening: number | null;
}

export type StatKey = 'str' | 'int' | 'pie' | 'vit' | 'agi' | 'dex' | 'luk';

export interface JobSkill extends LocalizedName {
    identification: number;
    get_lv: number | null;
}

export interface JobDetail extends LocalizedName {
    id: number;
    abbreviation?: string | null;
    display_order: number;
    category: 'standard' | 'collab' | 'character' | 'other';
    alignment: Record<string, boolean>;
    base: Record<string, number | null>;
    growth: Record<string, number | null>;
    multipliers: Record<string, number | null>;
    skills: JobSkill[];
    skill_variants: Record<string, JobSkill[]>;
    skill_count: number;
    characters: { primary: number[]; changeable: number[] };
    /** 转职到本职业所需的道具（按角色组给，道具名暂缺） */
    change_items: Array<{ item: number | null; quantity: number | null; group: number | null }>;
}

/** 装备数值：攻击 / 次数 / 魔力 / 神力 / 防御 / 魔防 / 速度 / 命中 / 会心 / 回避 / 抵抗 / 探索三项 */
export interface EquipmentStat {
    atk: number;
    c: number;
    mag: number;
    div: number;
    def: number;
    mdef: number;
    spe: number;
    acc: number;
    sur: number;
    eva: number;
    res: number;
    /** 探知 */
    det: number;
    /** 陷阱解除 */
    dtrap: number;
    /** 陷阱回避 */
    etrap: number;
}

export type EquipmentStatKey = keyof EquipmentStat;

/**
 * 类型基准值（``EquipmentResponse.baseStat``）：键是类型名（含 ``R{阶级}`` 变体）。
 * ``i`` 是类型按钮的排序序号（< 100 武器 / >= 100 防具），
 * 其余属性 ``-1`` 表示不参与比较，缺省按 0 处理。
 */
export type EquipmentBaseStatEntry = { i: number } & Partial<Record<EquipmentStatKey, number>>;

export type EquipmentBaseStat = Record<string, EquipmentBaseStatEntry>;

/**
 * 装备特性：只存技能 identification（+ 装备引用的等级），
 * 名字与说明由前端从技能数据（IndexedDB）里查。
 */
export interface EquipmentRef {
    /** ``Skill.identification``（纯 lock config 特性则是 ``EquipmentLockConfig.id``） */
    id: number;
    /** 装备引用的技能等级（1 级不写） */
    level?: number;
    /** 展示型 lock config 特性的名字（技能数据里查不到） */
    name?: string;
    /** 展示型 lock config 特性的手写说明（游戏里没有这段文本） */
    desc?: string | null;
}

/** 强化曲线的一行：该等级的完整数值（只输出与 +0 不同的等级） */
export interface EquipmentLevel extends Partial<EquipmentStat> {
    lv: number;
}

/**
 * 材质补强（合材补强）的一行。``rank`` 是**目标阶级**、``level`` 是该阶级内的
 * 次数；五项属性是累计加成（新阶级第 1 次接着上一阶级满次继续加），
 * 武器只有 atk / mag / div，防具只有 def / mdef。
 */
export interface EquipmentOverRank {
    rank: number;
    level: number;
    /** 金币消耗 */
    cost: number;
    atk: number;
    mag: number;
    div: number;
    def: number;
    mdef: number;
}

export interface EquipmentSetSkill {
    id: number;
    skill_id: number;
    skill_name: string | null;
    require_count: number | null;
    max_level: number | null;
    add_skill_level: number;
}

/**
 * 一件装备（一个 identification）。列表与详情共用同一条记录：
 * 841 条装备体积很小，不需要像技能那样拆两级。
 */
export interface EquipmentListItem extends LocalizedName {
    id: number;
    /** 武器 / 盾 / 头部 / 身体 / 手部 / 脚部 / 饰品 / 工具 */
    category: string;
    type_id: number | null;
    /** 短剑 / 单手剑 / 双手斧 … */
    type: string | null;
    part: number | null;
    /** 阶级 */
    rank: number;
    /** 图鉴编号；特殊装备（图鉴 ``display_type`` 2）为 ``"EX"``，没有图鉴记录为 null */
    collection_id: number | 'EX' | null;
    element: number;
    element_name: string | null;
    /** 特典 / 活动装备 */
    special: boolean;
    /** 客户端备注（日文） */
    note: string | null;
    /** 列表图标资源名（不含 ``.png``，与其它 wiki 图片同目录） */
    list_icon: string | null;
    /** 背包大图标资源名（不含 ``.png``） */
    icon: string | null;
    /** 特典分类：9 = 特典，0 = 普通（来自 ``Api/GetV2Equipment`` 的 extra） */
    soucate: number;
    /** 中文说明（解包/接口暂未提供，占位） */
    desc: string | null;
    /** 获取途径（wiki 手工补充，支持 ``[[页面|文字]]`` 链接） */
    sou: string[];
    /** 装备需求（解包/接口暂未提供，占位） */
    req: string[];
    /**
     * 妖精标记（解包 ``Equipment.conditions_*`` 的种族条件）：
     * 0 = 不适用（妖精能穿但发挥不出性能）/ 1 = 可用（妖精与非妖精都能穿）/
     * 2 = 专用（只有妖精能穿）
     */
    fa_can: number;
    /** 妖精技能 = 套装技能名；多个用「、」连接，没有套装技能为 null */
    fa_sk: string | null;
    /** 妖精技能说明（套装技能说明，中文） */
    fa_sk_desc: string | null;
    /** 职业限制（``Job.id``）；空数组 = 不限职业 */
    job_limited: number[];
    /** 种族限制（``CharacterSpecies.id``）；空数组 = 不限种族 */
    race_limited: number[];
    /** 强化曲线（每个等级一行完整数值） */
    levels: EquipmentLevel[];
    /** 加护概率：4 个槽位 × 19 个属性 */
    bonus: number[][] | null;
    /** 强化上限 */
    reinforce_max: number;
    /** 材质补强（目标阶级从当前+1 起；空数组 = 已是最上位阶级） */
    over_rank: EquipmentOverRank[];
    /** 0 级数值 */
    stats: EquipmentStat;
    /** 满强化推算值（base + 强化组，仅供参考） */
    max_stats: EquipmentStat;
    /** 装备类型特性 */
    skills: EquipmentRef[];
    /** 非装备类型特性 */
    traits: EquipmentRef[];
    set_skills: EquipmentSetSkill[];
    /** 商店来源（空数组 = 商店买不到） */
    shop: EquipmentShopRow[];
}

export interface EquipmentShopRow {
    /** 商店展示名，如「金币商店 · 全城镇通用」 */
    shop_name?: string;
    price?: number;
    /** 货币名；兑换点数时是实际点数名 */
    currency_name?: string;
}

export interface EquipmentDetail extends EquipmentListItem {}

export interface EffectParamLabel {
    /** 名称；末尾带 ``%`` 表示该值是百分数（显示时 ``%`` 移到数值后面） */
    name: string;
    /** @deprecated 旧数据里的单位，现已改用名称末尾的 ``%`` */
    unit?: string;
}

/**
 * 参数标注：优先直接写字符串（``"武器@eq"``），也兼容旧的 ``{ "name": "武器@eq" }`` 写法。
 * 末尾 ``%`` = 百分数，末尾 ``@xx`` = 这个数字是某个枚举的 id（见 SkillDetail 的 REF_TAG）。
 */
export type EffectParamEntry = string | EffectParamLabel;

/** 取出标注文本（字符串 / 对象都支持） */
export const effectParamText = (entry?: EffectParamEntry | null): string => {
    if (entry == null) return '';
    return typeof entry === 'string' ? entry : entry.name;
};

/** 旧写法里的 ``unit``（只有对象才有） */
export const effectParamUnit = (entry?: EffectParamEntry | null): string | undefined =>
    entry != null && typeof entry !== 'string' ? entry.unit : undefined;

export interface EffectKind {
    id: number;
    name: string | null;
    name_jp: string | null;
    category: number | null;
    primary_category: number | null;
    count: number;
    /** labels for param_1..7; null position = unknown / unused */
    params?: Array<EffectParamEntry | null> | null;
    /** 互斥 / 互相移除的效果种类（暂无可读枚举） */
    invalid_kinds?: number[] | null;
    remove_kinds?: number[] | null;
}

/** 召唤出来的单位：敌人分类 + 等级 + 数量 */
export interface SkillSummon {
    category: number;
    level: number;
    count: number;
}

export interface SkillListItem extends LocalizedName {
    identification: number;
    kind: number | null;
    kind_name: string | null;
    max_level: number;
    is_passive: boolean;
    player: boolean;
    sources: string[];
    jobs: number[];
    /** 召唤出来的单位（``EnemyFriendLayout``） */
    summons: SkillSummon[];
    flags: { test: boolean; level0: boolean; player: boolean };
    /** 技能用到的 sub effect kind（去重升序），供列表按 ID 精确筛选 */
    sub_kinds: number[];
}

export interface SkillDamage {
    attack_rate: number | null;
    attack_rate_both_hands?: number | null;
    add_damage_rate: number | null;
    add_critical_rate?: number | null;
    valid_cap_parameter_value?: number | null;
    valid_cap_parameter_value_both_hands?: number | null;
    valid_start_parameter_value?: number | null;
    damage_type: number | null;
    attack_type?: number | null;
    /** stat the attack rate is a percentage of (SkillReferenceParamType) */
    reference_parameter?: number | null;
    /** second stat scaled into the attack rate (double-scaling skills) */
    reference_parameter_2?: number | null;
    /** element ids: 1 fire .. 7 untyped, 99 physical, 999 none */
    aptitude_ids?: number[];
    fixed_damage: number | null;
    hit_rate: number | null;
    damage_count: number | null;
    only_once?: boolean | null;
    target: number | null;
    target_text: string | null;
}

/** 被引用的 sub effect 的摘要（用于把「追加子效果 / 扩展参数」展开成描述） */
export interface SubEffectBriefLeaf {
    id: number;
    kind: number | null;
    kind_name: string | null;
    params: number[] | null;
    strength: number | null;
    turn: number | null;
    target: number | null;
    target_text: string | null;
    /** 效果量（恢复量）：参照能力值、百分比与阈值窗口 */
    calc_reference_parameter?: number | null;
    calc_reference_parameter_2?: number | null;
    calc_reference_parameter_rate?: number | null;
    calc_reference_parameter_rate_2?: number | null;
    calc_valid_cap_parameter_value?: number | null;
    calc_valid_start_parameter_value?: number | null;
}

/** 只再展开一层：``children`` 是叶子 */
export interface SubEffectBrief extends SubEffectBriefLeaf {
    children: SubEffectBriefLeaf[];
}

/** kind 2790 的档位：`step` 是敌人 buff 数量档，`effect_group` 是实际执行的技能效果组 */
export interface StepReplace {
    step: number;
    effect_group: number;
    effects: SubEffectBriefLeaf[];
}

export interface SkillSubEffect {
    kind: number | null;
    kind_name: string | null;
    strength: number | null;
    turn: number | null;
    target: number | null;
    target_text: string | null;
    params?: Array<number | null>;
    /** labels for ``params``, from effect_kinds.json */
    param_labels?: Array<EffectParamEntry | null> | null;
    /** where the sub effect was attached: the damage row, the effect group, or the attack start */
    from?: 'damage' | 'effect_group' | 'attack_start';
    /** ``SkillSubEffect.reference_parameter`` (SkillReferenceParamType id) */
    reference_parameter?: number | null;
    /** base apply rate in percent; the actual rate scales with ``reference_parameter`` */
    reference_parameter_rate?: number | null;
    /** stat value below which the apply rate is 0 */
    abnormal_valid_start_parameter_value?: number | null;
    /** stat value at which the apply rate reaches 100% */
    abnormal_valid_cap_parameter_value?: number | null;
    /** the effect ignores the apply check entirely */
    force_apply?: boolean | null;
    /** resistance is not subtracted from the apply rate */
    is_ignore_resist?: boolean | null;
    /** 施加率参照的抗性类型（暂无可读枚举） */
    reference_resist?: number | null;
    /** 追加的子效果 id */
    child_sub_effect_ids?: number[] | null;
    /** 只对特定种族生效 */
    target_race_ids?: number[] | null;
    /** ``SkillSubEffectExtensionParam`` 的扩展参数（多数是别的 sub effect id） */
    extension_params?: number[] | null;
    /** 参数里指向的效果（参数序号 -> 被引用效果的摘要） */
    param_refs?: Record<string, SubEffectBrief> | null;
    /** ``child_sub_effect_ids`` 的展开版 */
    child_sub_effects?: SubEffectBrief[] | null;
    /** ``extension_params`` 的展开版 */
    extension_effects?: SubEffectBrief[] | null;
    /** kind 2790：按敌人 buff 数量档替换的效果组 */
    step_replace?: StepReplace[] | null;
    /** 效果量（恢复量等）参照的能力值：2 魔力 / 3 神力 / 22 信仰 / 23 体力 / 25 灵巧 / 26 运气 / 27 等级 */
    calc_reference_parameter?: number | null;
    /** 第二个参照能力值（双属性折算时用） */
    calc_reference_parameter_2?: number | null;
    /** 效果量占参照能力的百分比，140 = 140% */
    calc_reference_parameter_rate?: number | null;
    /** 第二个参照能力值的百分比 */
    calc_reference_parameter_rate_2?: number | null;
    /** 效果量的参数上限（阈值），如 100 / 800 */
    calc_valid_cap_parameter_value?: number | null;
    /** 效果量的阈值起点 */
    calc_valid_start_parameter_value?: number | null;
}

export interface SkillLevel {
    level: number;
    cost: number | null;
    cost_kind: number | null;
    use_timing: number | null;
    /** 每场战斗的可用次数（0 = 不限） */
    use_limit?: number | null;
    /** 仇恨值 */
    hate?: number | null;
    /** 技能射程：0 近距离 / 1 中距离 / 10 远距离 / 99 依武器 */
    range_type?: number | null;
    /** 使用条件 id（暂无可读枚举） */
    skill_condition_ids?: number[] | null;
    effect_group?: number;
    passive_effect_groups?: number[];
    description?: string;
    description_lang?: string;
    /** 该等级自己的名字（多级技能名字不同时才有） */
    name?: string;
    name_lang?: string;
    damage?: SkillDamage[];
    sub_effects?: SkillSubEffect[];
}

export interface SkillLearn {
    job: number;
    get_lv: number | null;
}

export interface SkillDetail extends SkillListItem {
    description: string | null;
    detail_description: string | null;
    description_lang?: string;
    job_limited: number[];
    equipment_limited: number[];
    tags: number[];
    levels: SkillLevel[];
    /** "Lv 3 盗贼" style unlock conditions */
    learn?: SkillLearn[];
}

/** 敌人数值块（公式输入）：`(base + growth * lv / 100) * correction / 100` */
export interface EnemyStat {
    base: number;
    growth: number;
    /** 修正率，100 = 原值 */
    correction: number;
    /** HP 浮动下限（百分数） */
    min: number;
    /** HP 浮动上限（百分数） */
    max: number;
}

export interface EnemyFreeze {
    half: number;
    full: number;
    break: number;
    recovery: number;
    wait_min: number;
    wait_max: number;
    intelligence: number;
}

/** AI 技能池里的一行：技能 + 随机权重 + 选目标的条件文案 */
export interface EnemyAiSkill {
    skill: SkillRef;
    /** 随机抽选权重 */
    weight: number;
    /** 选目标的条件文案，null = 默认目标 */
    target: string | null;
}

/** 一条触发条件：整段文案，或「前缀 + 敌人分类 id / 子效果种类 id + 后缀」 */
export interface EnemyAiCondition {
    /** 整段文案（没有链接时使用，未知类型为 ``type N``） */
    text: string | null;
    /** 链接前缀，例如「单位」/「敌人分类」/「我方」 */
    label: string | null;
    /** ``EnemyCategory.id`` */
    ref: number | null;
    /** ``SkillSubEffectKind.id``，名称走 ``effectKinds`` */
    status: number | null;
    /** 链接后缀，例如「存在」/「2 人以上」 */
    suffix: string | null;
}

/** AI 行动规则的一行 = 一条「条件成立 → 用这个技能池」 */
export interface EnemyAiRule {
    /** 判定顺序，小的先检查（第一条条件全部成立的行胜出） */
    priority: number;
    /** 触发条件（多条之间是「且」） */
    conditions: EnemyAiCondition[];
    skills: EnemyAiSkill[];
}

/** 插入（割り込み）技能：``EnemyInterruptAction`` 的一种触发方式，按技能合并 */
export interface EnemyInterrupt {
    skill: SkillRef;
    /** 整场战斗只能用一次（参考站写作「插入・一次」） */
    once: boolean;
    /** HP 阈值（%），null = 不是 HP 触发的插入 */
    hp: number | null;
    /** 触发条件（与 AI 行动规则同一套结构，多条之间是「且」） */
    conditions: EnemyAiCondition[];
}

/** 一个出现变体（一个 Enemy 行） */
export interface EnemyVariant {
    id: number;
    kind: number;
    kind_name: string | null;
    param: number;
    exp: number;
    ai: number;
    level_min: number;
    level_max: number;
    attribute: Ref[];
    attack_attribute: Ref[];
    weak: Ref[];
    characteristics: Ref[];
    gimmicks: number[];
    fly: boolean;
    body_size: number[];
    /** 全部技能（行动 + 插入 + 被动 + 挣扎） */
    skills: SkillRef[];
    /** 行动技能（AI 技能组，不含插入） */
    action_skills: SkillRef[];
    /** 插入（割り込み）技能：带「一次」标记与 HP 触发条件 */
    interrupts: EnemyInterrupt[];
    /** 被动技能 */
    passive_skills: SkillRef[];
    /** 挣扎（反撃 / もがき）技能 */
    struggle_skill: SkillRef | null;
    /** AI 行动规则：priority 升序，条件成立就用该技能池 */
    ai_plan: EnemyAiRule[];
    stats: Record<string, EnemyStat>;
    resist: Record<string, number>;
    freeze: EnemyFreeze;
}

/** 一条 = 一个 EnemyCategory（图鉴条目 + 只在解包数据里存在的分类） */
export interface EnemyListItem extends LocalizedName {
    id: number;
    /** 图鉴编号；null = 没有图鉴记录 */
    no: number | null;
    book: number | null;
    /** wiki 缩略图（去掉 `_s.png` 后缀） */
    thumbnail: string | null;
    boss: boolean;
    /** 敌人种族（EnemySpecies） */
    race: Ref;
    lineage: number;
    /** 体型档位 1 小 / 2 中 / 3 大 / 4 特大 */
    size: number;
    size_name: string | null;
    attack_type: number;
    damage_type: number;
    attribute: Ref[];
    attack_attribute: Ref[];
    weak: Ref[];
    characteristics: Ref[];
    gimmicks: number[];
    /** 出现的强度档位 */
    kinds: number[];
    kind_names: string[];
    level: { min: number; max: number } | null;
    fly: boolean;
    body_size: Array<{ size: number[]; count: number }>;
    resist: Record<string, number>;
    freeze: EnemyFreeze;
    skills: SkillRef[];
    variants: EnemyVariant[];
}

export type EnemyDetail = EnemyListItem;

export interface Manifest {
    /** ``Api/Version`` payload - the only value the cache is keyed on */
    version: number | null;
    source: string;
    counts: {
        characters: number;
        character_groups: number;
        excluded_awakening: number;
        jobs: number;
        skills: number;
        player_skills: number;
        equipments: number;
    };
    notes: string[];
}
